<body>
<svg id="stage" viewBox="0 0 1280 720" preserveAspectRatio="xMidYMid slice">
  <defs>
    <!-- fleece silhouette, reused for shading clips -->
    <path id="fleece" d="M -96,-6 C -103,-30 -92,-50 -68,-52 C -60,-66 -34,-63 -24,-56
      C -16,-70 10,-73 26,-61 C 34,-77 66,-76 76,-58 C 94,-60 106,-42 102,-20
      C 114,2 112,26 100,40 C 96,58 76,66 58,64 C 48,76 18,78 4,70
      C -14,80 -44,78 -54,66 C -84,72 -102,46 -96,-6 Z"/>
    <clipPath id="fleeceClip"><use href="#fleece"/></clipPath>

    <!-- print-grain filter -->
    <filter id="grain" x="0" y="0" width="100%" height="100%">
      <feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="2" stitchTiles="stitch"/>
      <feColorMatrix type="matrix" values="0 0 0 0 0.24  0 0 0 0 0.19  0 0 0 0 0.12  0.55 0 0 0 -0.12"/>
