    <radialGradient id="shadowGrad" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#42502F" stop-opacity="0.30"/>
      <stop offset="70%" stop-color="#42502F" stop-opacity="0.14"/>
