    </radialGradient>
  </defs>

  <!-- ======================= SKY ======================= -->
  <rect x="-20" y="-20" width="1320" height="760" fill="#F2DECA"/>

  <!-- sun, with a slight riso mis-registration -->
  <g>
    <circle cx="1042" cy="306" r="92" fill="#E79A55"/>
