  </g>

  <g id="gClouds"></g>

  <!-- birds -->
  <g id="gBirds" stroke="#6E4A30" stroke-width="1.8" fill="none" stroke-linecap="round"></g>

  <!-- ======================= RIDGES ======================= -->
  <g id="gRidgeFar">
    <path d="M0,372 C120,346 240,346 360,368 C470,386 560,352 680,358 C800,364 900,340 1020,352 C1110,360 1200,372 1280,372 L1280,404 L0,404 Z" fill="#F0D9B4"/>
  </g>
  <g id="gRidgeMid">
    <path d="M0,392 C100,386 170,300 260,306 C330,310 380,378 470,372 C540,366 600,264 690,276 C760,286 800,372 900,368 C1000,364 1080,300 1170,312 C1230,320 1260,386 1280,392 L1280,404 L0,404 Z" fill="#E2A87F"/>
  </g>
  <g id="gRidgeNear">
    <path d="M0,392 C120,380 240,398 360,388 C500,374 640,402 780,386 C900,372 1050,398 1160,390 C1210,386 1250,392 1280,392 L1280,408 L0,408 Z" fill="#CE9068"/>
  </g>

  <!-- ======================= GROUND ======================= -->
  <rect x="-20" y="398" width="1320" height="340" fill="#9CAA80"/>
  <rect x="-20" y="548" width="1320" height="118" fill="#8B9C71"/>
  <rect x="-20" y="666" width="1320" height="80" fill="#7F9068"/>

  <g id="gPlain"></g>
  <g id="gLane"></g>
  <g id="gFringe"></g>

  <!-- contact shadow -->
  <ellipse id="alpShadow" cx="470" cy="608" rx="150" ry="20" fill="url(#shadowGrad)"/>

  <!-- ======================= ALPACA ======================= -->
  <g id="alpaca" transform="translate(470,462)">
    <!-- far-side legs (darker, higher = further away) -->
    <g id="legFarF"></g><g id="legFarR"></g>
    <!-- near-side legs -->
    <g id="legNearF"></g><g id="legNearR"></g>

    <!-- tail -->
    <g id="tail" transform="translate(-100,-18)">
      <circle r="13" fill="#F4E9D4"/><circle cx="-2" cy="2" r="7" fill="#EBDCC0"/>
    </g>

    <!-- torso -->
    <use href="#fleece" fill="#F4E9D4"/>
    <g clip-path="url(#fleeceClip)">
      <ellipse cx="0" cy="58" rx="108" ry="34" fill="#E3D2B2" opacity="0.6"/>
      <ellipse cx="-60" cy="4" rx="58" ry="48" fill="#EBDCBE" opacity="0.5"/>
      <!-- fleece crimp curls -->
      <g stroke="#D6BE96" stroke-width="2.4" stroke-linecap="round" fill="none" opacity="0.75">
        <path d="M -70,-26 q 11,-9 21,-1"/><path d="M -46,-40 q 10,-8 20,-1"/>
        <path d="M -66,8 q 12,-10 24,-2"/><path d="M -22,18 q 13,-10 25,-1"/>
        <path d="M 8,10 q 12,-9 23,-1"/><path d="M -34,-14 q 10,-9 21,-2"/>
        <path d="M 34,-22 q 11,-8 21,0"/>
      </g>
    </g>

    <!-- neck + head spine -->
    <g id="spine" transform="translate(55,-10)">
      <path d="M -18,10 C -20,-60 -16,-120 -14,-146 L 12,-146 C 14,-108 18,-52 26,10 Z" fill="#F4E9D4"/>
      <circle cx="14" cy="-118" r="9"  fill="#F4E9D4"/>
      <circle cx="13" cy="-100" r="10" fill="#F4E9D4"/>
      <circle cx="12" cy="-78"  r="11" fill="#F4E9D4"/>
      <circle cx="10" cy="-52"  r="12" fill="#F4E9D4"/>
      <circle cx="8"  cy="-26"  r="13" fill="#F4E9D4"/>
      <!-- chest ruff -->
      <circle cx="30" cy="34" r="10" fill="#F4E9D4"/>
      <circle cx="25" cy="50" r="9"  fill="#EFE3CB"/>
      <circle cx="27" cy="64" r="8"  fill="#F4E9D4"/>

      <!-- head -->
      <g id="head" transform="translate(-1,-148)">
        <!-- ears behind skull -->
        <g id="earL" transform="translate(-4,-28)">
          <path d="M -4,0 C -10,-10 -12,-24 -6,-33 C -2,-38 3,-35 4,-28 C 6,-18 5,-6 2,0 Z" fill="#EBD9BC"/>
          <path d="M -3,-3 C -7,-11 -8,-21 -4,-27 C -1,-30 2,-28 2,-23 C 3,-16 2,-8 0,-3 Z" fill="#E2B596" opacity="0.7"/>
        </g>
        <g id="earR" transform="translate(11,-27)">
          <path d="M 4,0 C 10,-10 12,-24 6,-33 C 2,-38 -3,-35 -4,-28 C -6,-18 -5,-6 -2,0 Z" fill="#EBD9BC"/>
          <path d="M 3,-3 C 7,-11 8,-21 4,-27 C 1,-30 -2,-28 -2,-23 C -3,-16 -2,-8 0,-3 Z" fill="#E2B596" opacity="0.7"/>
        </g>

        <!-- forelock -->
        <circle cx="-2" cy="-28" r="11" fill="#F4E9D4"/>
        <circle cx="8"  cy="-30" r="10" fill="#EFE3CB"/>
        <circle cx="17" cy="-26" r="8"  fill="#F4E9D4"/>

        <!-- skull + muzzle -->
        <path d="M -20,-14 C -20,-30 -6,-36 6,-33 C 18,-31 30,-24 44,-12 C 52,-5 53,4 46,8 C 34,16 12,18 -2,16 C -16,14 -22,4 -22,-6 Z" fill="#F4E9D4"/>
        <ellipse cx="26" cy="4" rx="15" ry="10" fill="#EFE3CB" opacity="0.8"/>

        <!-- face -->
        <path d="M 38,8 q 5,4 10,-1" stroke="#4A3A2C" stroke-width="1.8" fill="none" stroke-linecap="round"/>
        <circle cx="45" cy="1" r="1.6" fill="#4A3A2C"/>
        <ellipse cx="30" cy="6" rx="5.5" ry="3" fill="#E7B199" opacity="0.55"/>
        <g id="eye">
          <ellipse cx="15" cy="-5" rx="4.4" ry="5" fill="#43332A"/>
          <circle cx="13.6" cy="-6.6" r="1.25" fill="#FFF7EA" opacity="0.9"/>
        </g>
      </g>
    </g>
  </g>

  <!-- dust motes -->
  <g id="gDust"></g>

  <!-- ======================= PRINT TEXT ======================= -->
  <text x="64" y="66" font-size="17" letter-spacing="5" fill="#7A5233" style="font-variant:small-caps">Afternoon, at her own pace</text>
  <text x="1216" y="66" font-size="15" letter-spacing="3" fill="#7A5233" text-anchor="end" style="font-variant:small-caps">Plate IV</text>
  <text x="1216" y="668" font-size="19" font-style="italic" fill="#6E4A30" text-anchor="end">she knows the way home.</text>

  <!-- grain -->
  <rect x="0" y="0" width="1280" height="720" filter="url(#grain)" opacity="0.45" style="mix-blend-mode:multiply"/>
</svg>

<script>
(function(){
"use strict";
var NS="http://www.w3.org/2000/svg";
function el(tag,attrs,parent){var n=document.createElementNS(NS,tag);for(var k in attrs)n.setAttribute(k,attrs[k]);if(parent)parent.appendChild(n);return n;}
function $(id){return document.getElementById(id);}
function rndGen(seed){var s=seed>>>0;return function(){s|=0;s=s+0x6D2B79F5|0;var t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}

/* ---------- timing ---------- */
var REDUCED=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
var CYCLE=REDUCED?3.4:1.55;      // one full stride
var DUTY=0.62;                   // fraction of cycle each foot is planted
var STRIDE_F=28,STRIDE_R=25;     // stance travel of front / hind feet
var WALK_SPEED=2*((STRIDE_F+STRIDE_R)/2)/(DUTY*CYCLE); // ~ ground scroll
var GROUND_N=142,GROUND_F=132;   // foot depth in alpaca-local units
var LIFT=15;

/* ============================================================
   PARALLAX SPRITES  (every layer loops over TILE, seamlessly)
============================================================ */
var TILE=1880,PAD=300;
function wrap(x){x=((x%TILE)+TILE)%TILE;return x-PAD;}

function makeLayer(groupId,speed,items,drawFn){
  var g=$(groupId),refs=[];
  items.forEach(function(it,i){
    refs.push({node:drawFn(g,it,i),it:it,x0:i/items.length*TILE});
  });
  return {
    update:function(t){
      refs.forEach(function(r){
        r.node.setAttribute("transform","translate("+wrap(r.x0-speed*t)+","+r.it.y+")");
      });
    }
  };
}
var R=rndGen(20240417);

/* --- clouds --- */
function cloudDraw(g,it){
  var n=el("g",{fill:it.c},g);
  el("rect",{x:0,y:0,width:it.s*2.4,height:it.s*0.62,rx:it.s*0.31,fill:it.c},n);
  el("circle",{cx:it.s*0.62,cy:-it.s*0.3,r:it.s*0.55,fill:it.c},n);
  el("circle",{cx:it.s*1.5,cy:-it.s*0.22,r:it.s*0.42,fill:it.c},n);
  return n;
}
var clouds=[
  {y:86,s:52,c:"#F8ECD8"},{y:158,s:38,c:"#F6E6CE"},{y:230,s:30,c:"#F3E0C4"},
  {y:118,s:26,c:"#F8ECD8"}
];
var Lclouds=makeLayer("gClouds",WALK_SPEED*0.11,clouds,cloudDraw);

/* --- bird flock --- */
var birdLayer=$("gBirds"),birdRefs=[];
[[900,148],[950,176],[860,196]].forEach(function(b,i){
  var n=el("path",{d:"M0,0 q6,-6 12,0 q6,-6 12,0"},birdLayer);
  birdRefs.push({n:n,x:b[0]+i*70,y:b[1],ph:i*1.7});
});

/* --- mid-plain trees & bushes --- */
function treeDraw(g,it){
  var n=el("g",{},g);
  el("rect",{x:-4,y:-34,width:8,height:36,rx:3,fill:"#8B6B4E"},n);
  el("circle",{cx:0,cy:-46,r:it.s,fill:"#8CA173"},n);
  el("circle",{cx:-it.s*0.7,cy:-36,r:it.s*0.66,fill:"#7F9468"},n);
  el("circle",{cx:it.s*0.72,cy:-38,r:it.s*0.6,fill:"#93A87B"},n);
  n.setAttribute("opacity",it.o);
  return n;
}
var plainItems=[{y:512,s:26,o:.85},{y:532,s:16,o:.7},{y:520,s:34,o:.8},{y:542,s:14,o:.6}];
var Lplain=makeLayer("gPlain",WALK_SPEED*0.62,plainItems,treeDraw);

/* --- lane: stones, tufts, flowers --- */
function laneDraw(g,it){
  if(it.k===0){ /* pebble */
    var n=el("g",{},g);
    el("ellipse",{cx:0,cy:0,rx:it.s,ry:it.s*0.55,fill:"#7C8D63"},n);
    el("ellipse",{cx:-it.s*0.2,cy:-it.s*0.16,rx:it.s*0.55,ry:it.s*0.3,fill:"#94A47B"},n);
    return n;
  }
  if(it.k===1){ /* grass tuft */
    var n=el("g",{stroke:"#6F8258","stroke-width":2.4,fill:"none","stroke-linecap":"round"},g);
    for(var b=-2;b<=2;b++)
      el("path",{d:"M0,0 Q"+(b*4)+","+(-it.s*0.7)+" "+(b*7)+","+(-it.s)},n);
    return n;
  }
  /* flower */
  var n=el("g",{},g);
  el("rect",{x:-1,y:-14,width:2,height:14,fill:"#6F8258"},n);
  el("circle",{cx:0,cy:-16,r:4.5,fill:"#E9A25F"},n);
  el("circle",{cx:0,cy:-16,r:1.6,fill:"#B0562F"},n);
  return n;
}
var laneKinds=[],nLane=11;
for(var i=0;i<nLane;i++)laneKinds.push(i%5<2?0:(i%5<4?1:2));
var laneItems=laneKinds.map(function(k,i){
  return {k:k,s:k===0?6+R()*5:(k===1?15+R()*10:1),y:556+R()*78};
});
var Llane=makeLayer("gLane",WALK_SPEED,laneItems,laneDraw);

/* --- nearest fringe tufts (fast, big) --- */
var fr=[]
for(i=0;i<9;i++){var rr=rndGen(700+i*37)();fr.push({s:26+rr*26,k:1,y:666+rr*40});}
var Lfringe=makeLayer("gFringe",WALK_SPEED*1.5,fr,function(g,it){
  var n=el("g",{stroke:"#5F7350","stroke-width":4,fill:"none","stroke-linecap":"round"},g);
  for(var b=-2;b<=2;b++)
    el("path",{d:"M0,0 Q"+(b*6)+","+(-it.s*0.7)+" "+(b*11)+","+(-it.s)},n);
  return n;
});

/* ============================================================
   LEGS — two-bone IK, walk-gait foot targets
============================================================ */
var FLEECE_N="#F4E9D4",FLEECE_F="#E2D0AF",HOOF="#6B4F39";

function buildLeg(host,tone,far){
  var gUp=el("g",{},host);
  el("rect",{x:-8.5,y:-4,width:17,height:70,rx:8.5,fill:tone},gUp);       // upper bone
  el("ellipse",{cx:0,cy:14,rx:11,ry:15,fill:tone},gUp);                    // thigh fuzz
  el("circle",{cx:0,cy:66,r:8.5,fill:tone},gUp);                           // knee cap
  var gLo=el("g",{},gUp);
  el("rect",{x:-6,y:-4,width:12,height:64,rx:6,fill:tone},gLo);            // lower bone
  el("ellipse",{cx:-1,cy:60,rx:9,ry:6.5,fill:tone},gLo);                   // foot
  el("path",{d:"M -10,58 A 10,7 0 0 0 8,58 Z",fill:HOOF,transform:"translate(0,4)"},gLo);
  return {gUp:gUp,gLo:gLo,far:far};
}

var legs=[
  {leg:null,hip:{x:76,y:16}, rest:82,S:STRIDE_F,off:0.31,ground:GROUND_N,bend:+1,near:true }, // front near
  {leg:null,hip:{x:70,y:6},  rest:74,S:STRIDE_F,off:0.81,ground:GROUND_F,bend:+1,near:false}, // front far
  {leg:null,hip:{x:-64,y:20},rest:-68,S:STRIDE_R,off:0.06,ground:GROUND_N,bend:-1,near:true },// hind near
  {leg:null,hip:{x:-58,y:10},rest:-60,S:STRIDE_R,off:0.56,ground:GROUND_F,bend:-1,near:false} // hind far
];
legs[0].leg=buildLeg($("legNearF"),FLEECE_N,false);
legs[1].leg=buildLeg($("legFarF"), FLEECE_F,true );
legs[2].leg=buildLeg($("legNearR"),FLEECE_N,false);
legs[3].leg=buildLeg($("legFarR"), FLEECE_F,true );

function ik(hx,hy,tx,ty,L1,L2,bend){
  var dx=tx-hx,dy=ty-hy,d=Math.sqrt(dx*dx+dy*dy);
  var lo=Math.abs(L1-L2)+1,hi=L1+L2-1;
  d=Math.max(lo,Math.min(hi,d));
  var a=Math.acos(Math.max(-1,Math.min(1,(L1*L1+d*d-L2*L2)/(2*L1*d))));
  var base=Math.atan2(dy,dx),A1=base+a*bend;
  var psi=Math.acos(Math.max(-1,Math.min(1,(L1*L1+L2*L2-d*d)/(2*L1*L2))));
  var dA2=-bend*psi;
  return {A1:A1,dA2:dA2};
}

/* ============================================================
   DUST
============================================================ */
var dustHost=$("gDust"),dustPool=[],dustLive=[];
for(i=0;i<36;i++)dustPool.push(el("circle",{r:3,fill:"#D9C5A0",opacity:0},dustHost));

function puff(x,y){
  for(var i=0;i<2;i++){
    if(!dustPool.length)return;
    var c=dustPool.pop();
    dustLive.push({n:c,x:x+(Math.random()-0.5)*8,y:y-Math.random()*3,
      vx:-18-Math.random()*22,vy:-14-Math.random()*26,life:0,ttl:0.55+Math.random()*0.3,r:2+Math.random()*2});
  }
}

/* ============================================================
   CHARACTER STATE
============================================================ */
var spine=$("spine"),head=$("head"),tail=$("tail"),eye=$("eye"),
    earL=$("earL"),earR=$("earR"),alpEl=$("alpaca"),shEl=$("alpShadow");

var flick={L:{next:2.6,t0:-9},R:{next:4.1,t0:-9}};
var blink={next:2.2,t0:-9};

function easeS(v){return v*v*(3-2*v);}

/* ============================================================
   MAIN LOOP
============================================================ */
var t0=null;
function frame(ts){
  if(t0===null)t0=ts;
  var t=(ts-t0)/1000,phi=(t/CYCLE)%1,w=phi*Math.PI*2;

  /* ----- world parallax ----- */
  Lclouds.update(t);Lplain.update(t);Llane.update(t);Lfringe.update(t);

  /* birds */
  birdRefs.forEach(function(b){
    var bx=((b.x-t*15)%1500+1500)%1500-110;
    var flap=0.55+0.45*Math.abs(Math.sin(t*9+b.ph));
    b.n.setAttribute("transform",
      "translate("+bx.toFixed(1)+","+(b.y+Math.sin(t*0.7+b.ph)*6).toFixed(1)+") scale(1,"+flap.toFixed(3)+")");
  });

  /* ----- body bob ----- */
  var bob=-3+2.3*Math.sin(2*w+0.6)+0.8*Math.sin(w);
  alpEl.setAttribute("transform","translate(470,"+(462+bob).toFixed(2)+")");
  shEl.setAttribute("cy",(608+bob*0.4).toFixed(2));
  shEl.setAttribute("rx",(150+Math.sin(2*w)*4).toFixed(1));

  /* ----- spine / neck ----- */
  var pitch=1.1*Math.sin(w+2.6);
  spine.setAttribute("transform","translate(55,-10) rotate("+pitch.toFixed(2)+")");

  var headLag=2.1*Math.sin(w-0.9);
  var nod=1.6*Math.sin(w+1.2);
  head.setAttribute("transform","translate(-1,"+(-148+headLag).toFixed(2)+") rotate("+nod.toFixed(2)+")");

  /* ear flicks */
  [["L",earL,-14],["R",earR,16]].forEach(function(e){
    var k=e[0],g=e[1],base=e[2],st=flick[k];
    if(t>=st.next){st.t0=t;st.next=t+3.5+Math.random()*5.5;}
    var dt=t-st.t0,env=dt<0.22?Math.sin(Math.PI*dt/0.22):0;
    var wob=1.6*Math.sin(t*5.1+(k==="L"?0:1.4));
    g.setAttribute("transform","translate("+(k==="L"?-4:11)+","+(k==="L"?-28:-27)+") rotate("+(base+wob+env*20)+")");
  });

  /* blink */
  if(t>=blink.next){blink.t0=t;blink.next=t+3+Math.random()*3;}
  var bd=t-blink.t0,open=bd<0.16?Math.min(1,0.1+0.9*Math.abs(1-bd/0.08)):1;
  eye.setAttribute("transform","translate(15,-5) scale(1,"+open.toFixed(2)+") translate(-15,5)");

  /* tail wag */
  tail.setAttribute("transform","translate(-100,-18) rotate("+(7*Math.sin(w+1)+2.5*Math.sin(2*w)).toFixed(2)+")");

  /* ----- legs ----- */
  legs.forEach(function(L){
    var p=(phi+L.off)%1,inStance=p<DUTY,tx,ty,droop=0;
    if(inStance){
      var u=p/DUTY;
      tx=L.rest+L.S-2*L.S*u;
      ty=604-(462+bob)-(L.far?8:0);
      if(L.wasSwing){ /* heel strike → dust */
        puff(470+tx,604+(L.far?-8:0));L.wasSwing=false;
      }
    }else{
      var v=(p-DUTY)/(1-DUTY),ev=easeS(v);
      tx=L.rest-L.S+2*L.S*ev;
      ty=(604-(462+bob)-(L.far?8:0))-Math.sin(Math.PI*v)*LIFT*(L.far?0.8:1);
      droop=Math.sin(Math.PI*Math.min(v*1.15,1))*7;
      L.wasSwing=true;
    }
    var sol=ik(L.hip.x,L.hip.y,tx,ty,70,62,L.bend);
    var A1deg=sol.A1*180/Math.PI,d2=(sol.dA2-droop*L.bend)*180/Math.PI;
    L.leg.gUp.setAttribute("transform","translate("+L.hip.x+","+L.hip.y+") rotate("+A1deg.toFixed(2)+")");
    L.leg.gLo.setAttribute("transform","translate(0,66) rotate("+d2.toFixed(2)+")");
  });

  /* ----- dust simulation ----- */
  for(i=dustLive.length-1;i>=0;i--){
    var d=dustLive[i];d.life+=1/60;
    var k=d.life/d.ttl;
    if(k>=1){d.n.setAttribute("opacity",0);dustPool.push(d.n);dustLive.splice(i,1);continue;}
    d.x+=d.vx/60;d.y+=d.vy/60;d.vy*=0.96;d.vx*=0.96;
    d.n.setAttribute("cx",d.x.toFixed(1));d.n.setAttribute("cy",d.y.toFixed(1));
    d.n.setAttribute("r",(d.r+k*5).toFixed(2));
    d.n.setAttribute("opacity",(0.45*(1-k)).toFixed(3));
  }

  requestAnimationFrame(frame);
}
